<?php require __DIR__.'/../middleware.php';api_method('POST');$d=json_decode(file_get_contents('php://input'),true);if(!is_array($d))$d=$_POST;$name=trim((string)($d['name']??''));$email=trim((string)($d['email']??''));$subject=trim((string)($d['subject']??'General enquiry'));$message=trim((string)($d['message']??''));if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||$message==='')api_json(['ok'=>false,'error'=>'Valid name, email, and message are required'],422);$q=db()->prepare('INSERT INTO contact_messages(name,email,subject,message,ip_hash) VALUES(?,?,?,?,?)');$q->execute([$name,$email,$subject,$message,hash('sha256',($_SERVER['REMOTE_ADDR']??'').(getenv('APP_KEY')?:'change-this'))]);api_json(['ok'=>true,'message'=>'Message received'],201);